package com.thomas.passiveeartraining.music

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.int
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * M4-T02: the production catalogs agree with the independent music21 fixtures.
 *
 * The fixtures are generated by `tools/music-fixtures` and checked byte-for-byte by
 * `scripts/check-music-fixtures.sh`; this test consumes them without starting Python.
 */
class FixtureCatalogTest {

    private fun resource(name: String): JsonObject {
        val text = javaClass.getResource("/music-fixtures/$name")?.readText()
            ?: error("missing fixture $name")
        return Json.parseToJsonElement(text).jsonObject
    }

    /** The library-neutral spelling triple, matching the fixture encoding. */
    private fun part(value: JsonObject): Triple<String, Int, Int> = Triple(
        value.getValue("letter").jsonPrimitive.content,
        value.getValue("accidental").jsonPrimitive.int,
        value.getValue("octave").jsonPrimitive.int
    )

    private fun part(pitch: SpelledPitch): Triple<String, Int, Int> =
        Triple(pitch.letter.name, pitch.accidental, pitch.writtenOctave)

    /** Parses a fixture root name such as `C#4` or `Db4` without using production spelling code. */
    private fun parseRoot(name: String): SpelledPitch {
        val letter = Letter.entries.first { it.name == name.first().toString() }
        val digits = name.takeLastWhile { it.isDigit() }
        val octave = digits.toInt()
        val marks = name.substring(1, name.length - digits.length)
        val accidental = when {
            marks.all { it == '#' } -> marks.length
            marks.all { it == 'b' } -> -marks.length
            marks.isEmpty() -> 0
            else -> error("unsupported fixture root spelling $name")
        }
        return SpelledPitch(letter, accidental, octave)
    }

    @Test
    fun everyChordFixtureMatchesTheCatalogInAllInversions() {
        val root = resource("chords.json")
        var checked = 0
        root.getValue("chords").jsonArray.forEach { element ->
            val fixture = element.jsonObject
            val quality = ChordQuality.ofIdOrNull(
                fixture.getValue("quality").jsonPrimitive.content
            ) ?: error("unknown quality")
            val rootName = fixture.getValue("root").jsonPrimitive.content
            val spelling = if ('b' in rootName) {
                SpellingPreference.FLAT
            } else {
                SpellingPreference.SHARP
            }
            val rootMidi = MidiNote.of(fixture.getValue("rootMidi").jsonPrimitive.int)
            val expectedMembers = fixture.getValue("members").jsonArray.map { part(it.jsonObject) }
            val rootPosition = ChordVoicing.of(quality, 0, rootMidi, spelling)
            assertEquals(
                "${fixture.getValue("root").jsonPrimitive.content} ${quality.id}",
                expectedMembers,
                rootPosition.spelledMembers().map { part(it) }
            )
            fixture.getValue("inversions").jsonArray.forEach { inversionElement ->
                val inversion = inversionElement.jsonObject
                val number = inversion.getValue("inversion").jsonPrimitive.int
                val sounding = inversion.getValue("sounding").jsonArray.map {
                    it.jsonPrimitive.int
                }
                val voicing = ChordVoicing.of(quality, number, rootMidi, spelling)
                assertEquals(
                    "sounding ${fixture.getValue("root").jsonPrimitive.content} ${quality.id} " +
                        "inversion $number",
                    sounding,
                    voicing.notes.map { it.value }
                )
                assertEquals(
                    inversion.getValue("bassMidi").jsonPrimitive.int,
                    voicing.bass.value
                )
                checked += 1
            }
        }
        assertTrue("fixtures must cover every quality and root", checked >= 264 * 3)
    }

    @Test
    fun everyScaleFixtureMatchesTheCatalogInBothDirections() {
        val root = resource("scales.json")
        var checked = 0
        root.getValue("scales").jsonArray.forEach { element ->
            val fixture = element.jsonObject
            val kind = ScaleKind.ofIdOrNull(fixture.getValue("kind").jsonPrimitive.content)
                ?: error("unknown scale kind")
            val tonic = parseRoot(fixture.getValue("root").jsonPrimitive.content)
            val ascending = ScaleTraversal.pitches(kind, tonic, ScaleDirection.ASCENDING)
            assertEquals(
                "${fixture.getValue("root").jsonPrimitive.content} ${kind.id}",
                fixture.getValue("ascending").jsonArray.map { part(it.jsonObject) },
                ascending.map { part(it) }
            )
            assertEquals(
                fixture.getValue("ascendingMidi").jsonArray.map { it.jsonPrimitive.int },
                ascending.map { it.midiValue }
            )
            val descending = ScaleTraversal.pitches(kind, tonic, ScaleDirection.DESCENDING)
            assertEquals(
                fixture.getValue("descendingMidi").jsonArray.map { it.jsonPrimitive.int },
                descending.map { it.midiValue }
            )
            val both = ScaleTraversal.pitches(kind, tonic, ScaleDirection.BOTH)
            assertEquals(
                fixture.getValue("bothMidi").jsonArray.map { it.jsonPrimitive.int },
                both.map { it.midiValue }
            )
            checked += 1
        }
        assertTrue("fixtures must cover every scale and root", checked >= 300)
    }

    @Test
    fun unrepresentableFixturesFailExplicitly() {
        val chords = resource("chords.json")
        assertEquals(
            "every chord fixture is representable within -2..2",
            0,
            chords.getValue("unrepresentable").jsonArray.size
        )
        val scales = resource("scales.json")
        scales.getValue("unrepresentable").jsonArray.forEach { element ->
            val fixture = element.jsonObject
            val kind = ScaleKind.ofIdOrNull(fixture.getValue("kind").jsonPrimitive.content)!!
            val tonic = parseRoot(fixture.getValue("root").jsonPrimitive.content)
            assertThrows(UnrepresentableSpellingException::class.java) {
                ScaleTraversal.pitches(kind, tonic, ScaleDirection.ASCENDING)
            }
        }
    }
}
